/** Parse a user-typed money amount ("12.5", "12,50") into integer cents. */
export function parsePrice(text: string): ParseResult {
  const t = text.trim().replace(/\s/g, '')
  if (t === '') return { ok: false, error: 'Enter a price.' }
  if (t.startsWith('-')) return { ok: false, error: 'Price cannot be negative.' }
  if (!NUMBER_RE.test(t)) return { ok: false, error: 'Price must be a number, e.g. 12.50.' }
  const [whole, frac = ''] = t.replace(',', '.').split('.')
  if (frac.length > 2) return { ok: false, error: 'Price can have at most 2 decimal places.' }
  const cents = Number(whole || '0') * 100 + Number(frac.padEnd(2, '0'))
  if (cents > 100_000_000) return { ok: false, error: 'Price is too large.' }
  return { ok: true, value: cents }
}

