    expect(buildSummary(bill, computeTotals(bill.people, [], 0, 0), 0, 0)).not.toContain('Settle up')
  })
})

describe('deserializeBill', () => {
  it('keeps payments and clears payers that no longer exist', () => {
    const raw = JSON.stringify({
